python3 - <<'EOF'
import json

with open('/data/orders.json') as f:
    orders = json.load(f)

totals = {}
for o in orders:
    totals[o['customer']] = totals.get(o['customer'], 0) + o['amount']

for customer, total in sorted(totals.items(), key=lambda kv: kv[1], reverse=True):
    print(f'{customer}: {total}')
EOF

